import {confirmSubmit} from './confirm-submit.js';
import {mountSaved} from './saved-materials.js';
import {createReadCache} from './read-cache.js';
import {speechSettings,wireSpeech,stopSpeech,speakerIcon} from './speech.js';
import {languageSwitcher,startLanguageUi} from './i18n.js';
const $=s=>document.querySelector(s), root=$('#app');
startLanguageUi(root,document.querySelector('#toast'));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let user=null,csrf='',meta={},cleanup=()=>{},routeVersion=0,loginPortal='employee';
const icons={edit:"M4 20l4-1L21 6l-3-3L5 16z M15 6l3 3",work:"M3 7h18v14H3z M8 7V4h8v3 M3 12h18 M10 11v3h4v-3",info:"M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7h.01",dashboard:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',learning:'M4 3h7v17H4z M11 5h9v17h-9 M6 7h3 M14 9h4',examination:'M7 4H4v18h16V4h-3 M8 2h8v5H8z M8 12h8 M8 16h5',ranking:'M7 3h10v6a5 5 0 0 1-10 0z M7 5H3v3a4 4 0 0 0 4 4 M17 5h4v3a4 4 0 0 1-4 4 M12 14v6 M7 21h10',profile:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0z M4 22v-3a8 8 0 0 1 16 0v3',employees:'M10 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0z M2 19v-3a5 5 0 0 1 10 0v3 M15 3a3 3 0 0 1 0 6 M15 12a5 5 0 0 1 6 5v2',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z M12 6v6l4 2',arrow:'M4 12h16 M14 6l6 6-6 6',logout:'M9 4H3v16h6 M9 12h12 M16 7l5 5-5 5'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[k]||icons.dashboard).split(' M').map((p,i)=>`<path d="${i?'M':''}${p}"/>`).join('')}</svg>`;
const num=(v,d=0)=>v==null?'—':Number(v).toLocaleString('id-ID',{maximumFractionDigits:d});
const date=(t,short=false)=>new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Makassar',day:'numeric',month:short?'short':'long',year:short?undefined:'numeric'}).format(new Date(t*1000));
const fmtTime=s=>`${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.max(0,s)%60).padStart(2,'0')}`;
const badge=(text,color='')=>`<span class="pill ${color}">${esc(text)}</span>`;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4000);}
const readCache=createReadCache();
async function api(path,{method='GET',body}={}){if(method!=='GET')readCache.invalidate();const load=async()=>{let res;try{res=await fetch('/api'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:body===undefined?undefined:JSON.stringify(body),signal:method==='GET'?AbortSignal.timeout(15000):undefined});}catch(error){if(error.name==='TimeoutError')throw Error('Koneksi terlalu lambat. Coba muat halaman kembali.');throw Error('Koneksi terputus. Jawaban yang belum tersimpan akan dicoba kembali selama halaman tetap terbuka.');}const data=await res.json();if(!res.ok){if(res.status===401&&user){readCache.invalidate();user=null;csrf='';location.hash='login';}throw Error(data.error||'Request gagal.');}return data;};try{return method==='GET'?await readCache.read(user?.id,path,load):await load();}finally{if(method!=='GET')readCache.invalidate();}}
function bind(id,event,fn){const el=$(id);if(el)el.addEventListener(event,fn);}
function form(id,fn){bind(id,'submit',async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('[type=submit]'),error=e.currentTarget.querySelector('.form-error');btn.disabled=true;if(error)error.textContent='';try{await fn(new FormData(e.currentTarget));}catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{btn.disabled=false;}});}
const empty=(title,copy='')=>`<div class="empty"><strong>${esc(title)}</strong>${esc(copy)}</div>`;
function demoBanner(){if(meta.demo&&meta.source_content)return '<div class="demo"><strong>AKUN UJI</strong> · Materi berasal dari sumber Anda · HSK 3.0 · Riwayat fixture lama tidak berlaku sebagai penentu level.</div>';return meta.demo?'<div class="demo"><strong>LINGKUNGAN DEMO</strong> · Akun, soal dan hasil uji sintetis. Bukan data karyawan atau konten resmi ECB.</div>':'';}
const brand=()=>'<div class="brand"><img src="/logo.png" alt="Logo ECB"><div><strong>ECB</strong><small>LANGUAGE PERFORMANCE SYSTEM</small></div></div>';
function shell(page,title,body){const leader=user.role==='leader',nav=leader?[['overview','Overview','dashboard'],['employees','Employees','employees'],['learning-analytics','Analitik Belajar','learning'],['results','Hasil Evaluasi','examination'],['ranking','Panggung Prestasi','ranking']]:[['dashboard','Dashboard','dashboard'],['learning','Learning','learning'],['examination','Examination','examination'],['ranking','Ranking','ranking'],['profile','Profile','profile']];root.innerHTML=`<div class="shell"><aside class="sidebar" id="portal-navigation"><button class="sidebar-close" id="close-menu" type="button" aria-label="Tutup navigasi">×</button>${brand()}<div class="nav-label">${leader?'LEADER PORTAL':'EMPLOYEE PORTAL'}</div><nav aria-label="Navigasi utama">${nav.map(([key,label,ic])=>`<a class="nav-item ${page===key?'active':''}" href="#${key}" ${page===key?'aria-current="page"':''}>${icon(ic)}${label}</a>`).join('')}</nav><div class="sidebar-bottom">${leader?'<p>Akun Leader bersama<br>Seluruh informasi bersifat read-only.</p>':'<p>一步一步，持续进步。<br>Selangkah demi selangkah,<br>terus bertumbuh.</p>'}<button class="nav-item w100" id="logout">${icon('logout')}Keluar</button></div></aside><button class="nav-backdrop" id="nav-backdrop" type="button" aria-label="Tutup navigasi" hidden tabindex="-1"></button><div class="main">${demoBanner()}<header class="topbar"><button class="menu-toggle" id="menu" aria-label="Buka navigasi" aria-controls="portal-navigation" aria-expanded="false">☰</button><div class="breadcrumb">${leader?'Leader':'Employee'} Portal &nbsp; / &nbsp; <span>${esc(title)}</span></div><div class="topbar-actions">${languageSwitcher()}<div class="user">${leader?'<div class="avatar">':'<a class="avatar profile-shortcut" href="#profile/edit" aria-label="Edit profil">'}${esc(user.name.replace('DEMO · ','').slice(0,2).toUpperCase())}${leader?'</div>':'</a>'}<div class="user-copy"><strong>${esc(user.name)}</strong><small>${esc(leader?'Akun bersama · Read-only':user.department)}</small></div></div></div></header><main class="content" id="main-content">${body}<div class="footer-note"><span>ECB Language Performance System</span><span>Waktu Indonesia Tengah · Asia/Makassar</span></div></main></div></div>`;const setMenu=open=>{$('.sidebar').classList.toggle('open',open);$('#menu').setAttribute('aria-expanded',String(open));$('#nav-backdrop').hidden=!open;if(open)$('#close-menu').focus();else $('#menu').focus();};bind('#menu','click',()=>setMenu(!$('.sidebar').classList.contains('open')));bind('#close-menu','click',()=>setMenu(false));bind('#nav-backdrop','click',()=>setMenu(false));root.onkeydown=e=>{if(e.key==='Escape'&&$('.sidebar')?.classList.contains('open'))setMenu(false);};document.querySelectorAll('.sidebar nav a').forEach(a=>a.addEventListener('click',()=>{if($('.sidebar').classList.contains('open'))setMenu(false);}));bind('#logout','click',async()=>{try{await api('/logout',{method:'POST',body:{}});user=null;csrf='';location.hash='login';}catch(e){toast(e.message);}});}
const heading=(eyebrow,title,copy,extra='',preserveTitle=false)=>`<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 ${preserveTitle?'data-i18n-skip':''}>${esc(title)}</h1><p>${esc(copy)}</p></div>${extra}</div>`;
const stat=(label,value,foot,ic='dashboard')=>`<div class="stat"><div class="stat-top"><span>${esc(label)}</span>${icon(ic)}</div><div class="stat-value">${value}</div><div class="stat-foot">${esc(foot)}</div></div>`;
const memoryLabels={known:'Hafal',review:'Ragu-ragu',unknown:'Belum hafal'};
function readingHTML(text,segments){return segments?segments.map(part=>part.pinyin?`<span class="hanzi-reading" data-i18n-skip><span lang="zh">${esc(part.text)}</span><small class="reading-pinyin">${esc(part.pinyin)}</small></span>`:esc(part.text)).join(''):esc(text);}
function speakButton(text){return /\p{Script=Han}/u.test(String(text||''))?`<button type="button" class="speak-button" data-speak="${encodeURIComponent(text)}" aria-label="Dengarkan pelafalan" aria-pressed="false">${speakerIcon} <span>Dengarkan</span></button>`:'';}
function memoryButtons(word){return `<div class="memory-badge">${badge(memoryLabels[word.memory_status]||'Belum ditandai',word.memory_status==='known'?'green':word.memory_status==='review'?'gold':'')}</div><div class="memory-actions" role="group" aria-label="Status hafalan">${Object.entries(memoryLabels).map(([state,label])=>`<button type="button" data-memory="${state}" data-word="${word.id}" class="memory-choice ${state}" aria-pressed="${word.memory_status===state}">${label}</button>`).join('')}</div>`;}
function memorySummary(words){const total=words.length,reviewed=words.filter(w=>w.memory_status).length,known=words.filter(w=>w.memory_status==='known').length,review=words.filter(w=>w.memory_status==='review').length,unknown=words.filter(w=>w.memory_status==='unknown').length,percent=total?Math.round(reviewed/total*100):0,mastery=total?Math.round(known/total*100):0;return `<section class="panel memory-summary"><div class="progress-copy"><strong>Progres pembelajaran</strong><strong>${percent}%</strong></div><div class="progress"><span data-progress="${percent}"></span></div><p class="memory-counts">${reviewed} / ${total} kosakata sudah dipelajari</p><div class="split">${badge(`${known} Hafal`,'green')}${badge(`${review} Ragu-ragu`,'gold')}${badge(`${unknown} Belum hafal`)}</div><p class="muted memory-counts">Penguasaan kosakata: ${mastery}%</p></section>`;}
function packageStatus(p){const labels={mastered:'Semua kosakata hafal',studied:'Sudah dipelajari',in_progress:'Sedang dipelajari',session_completed:'Sesi belajar selesai',not_started:'Belum dipelajari'};return `<div class="package-progress">${badge(labels[p.study_status]||'Belum dipelajari',['mastered','studied'].includes(p.study_status)?'green':p.reviewed_count?'gold':'')}<div class="progress-copy"><span>Progres pembelajaran</span><strong>${p.learning_percent||0}%</strong></div><div class="progress"><span data-progress="${p.learning_percent||0}"></span></div><small>${p.reviewed_count||0} / ${p.word_count} kosakata dipelajari · ${p.mastery_percent||0}% hafal</small></div>`;}
function learningOverview(packages){const total=packages.reduce((n,p)=>n+Number(p.word_count),0),reviewed=packages.reduce((n,p)=>n+Number(p.reviewed_count||0),0),known=packages.reduce((n,p)=>n+Number(p.known_count||0),0),percent=total?Math.round(reviewed/total*100):0;return `<section class="panel learning-overview mb"><div class="panel-head"><h2>Progres pembelajaran</h2>${badge(`${percent}%`,'green')}</div><div class="progress"><span data-progress="${percent}"></span></div><p class="memory-counts">${reviewed} / ${total} kosakata sudah dipelajari</p><p class="muted">${known} kosakata hafal · ${packages.filter(p=>p.study_status==='studied'||p.study_status==='mastered').length} / ${packages.length} paket selesai</p></section>`;}
function latestAttempt(d,track,mode){return d.history.find(r=>r.track===track&&r.mode===mode&&r.status!=='void'&&(mode==='weekly'?r.started_at>=d.weekly.start&&r.started_at<d.weekly.end:true)&&(track!=='hsk'||mode==='placement'||Number(r.level)===Number(d.profile.placement_level||1)));}
function attemptBadge(attempt){if(!attempt)return badge('Belum dikerjakan');if(attempt.status==='submitted'&&attempt.score==null)return badge('Menunggu penilaian','gold');if(attempt.status==='active')return badge('Sedang dikerjakan','gold');return badge(Number(attempt.passed)?'Lulus':'Belum lulus',Number(attempt.passed)?'green':'gold');}
function attemptDetail(attempt){return `<div class="attempt-status">${attemptBadge(attempt)}${attempt&&attempt.status!=='active'?`<span>Nilai: ${num(attempt.score,1)}</span><a href="#exam/${attempt.id}">Lihat hasil →</a>`:''}</div>`;}
function weeklyProgress(d){const completed=Number(!!d.weekly.hsk)+Number(!!d.weekly.work),passed=Number(!!d.weekly.hsk&&!!Number(d.weekly.hsk.passed))+Number(!!d.weekly.work&&!!Number(d.weekly.work.passed));return `<section class="panel mb"><div class="panel-head"><h2>Progres ujian mingguan</h2>${badge(`${completed*50}%`,completed===2?'green':'gold')}</div><div class="progress"><span data-progress="${completed*50}"></span></div><p class="memory-counts">${completed} / 2 ujian selesai · ${passed} / 2 ujian lulus</p><p class="muted">Latihan dan hasil kelulusan ditandai terpisah dari penyelesaian ujian wajib.</p></section>`;}
function wireMemory(words){document.querySelectorAll('[data-memory]').forEach(button=>button.onclick=async()=>{const word=words.find(w=>w.id===button.dataset.word),card=button.closest('[data-vocab]');if(!word||word.memory_status===button.dataset.memory)return;const buttons=card.querySelectorAll('[data-memory]');buttons.forEach(b=>b.disabled=true);try{const saved=await api(`/vocabulary/${word.id}/progress`,{method:'PUT',body:{status:button.dataset.memory}});word.memory_status=saved.status;buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.memory===saved.status)));card.querySelector('.memory-badge').innerHTML=badge(memoryLabels[saved.status],saved.status==='known'?'green':saved.status==='review'?'gold':'');$('#memory-summary').innerHTML=memorySummary(words);applyProgress();}catch(error){toast(error.message);}finally{buttons.forEach(b=>b.disabled=false);}});}
function authView(mode='login'){
 root.innerHTML=`${demoBanner()}<div class="auth-page"><div class="auth-story">${brand()}<section><div class="eyebrow">LEARN · PRACTICE · PROGRESS</div><div class="auth-hanzi" lang="zh">共同进步</div><h1>Bahasa membuka<br>lebih banyak<br>kesempatan.</h1><p>Bangun kemampuan Mandarin Anda. Hubungkan pembelajaran dengan pekerjaan, satu langkah setiap hari.</p></section><footer>PT ECB &nbsp; / &nbsp; LANGUAGE PERFORMANCE SYSTEM</footer></div><main class="auth-form"><div class="auth-language">${languageSwitcher()}</div>${mode==='register'?registerHTML():mode==='forgot'?forgotHTML():mode==='recovery'?resetHTML():loginHTML()}</main></div>`;
 if(mode==='login'){
  document.querySelectorAll('[data-portal]').forEach(b=>b.onclick=()=>{loginPortal=b.dataset.portal;authView();});
  form('#login-form',async fd=>{const data=await api('/login',{method:'POST',body:Object.fromEntries(fd)});user=data.user;csrf=data.csrf;location.hash=user.role==='leader'?'overview':'dashboard';});
 }else if(mode==='register')form('#register-form',async fd=>{const b=Object.fromEntries(fd);b.self_level=Number(b.self_level);await api('/register',{method:'POST',body:b});toast('Registrasi berhasil. Username Anda adalah nomor ID.');location.hash='login';});
 else if(mode==='forgot')form('#forgot-form',async fd=>{const r=await api('/forgot',{method:'POST',body:Object.fromEntries(fd)});$('#auth-message').textContent=r.message;});
 else if(mode==='recovery')form('#reset-form',async fd=>{const r=await api('/reset',{method:'POST',body:{password:fd.get('password'),access_token:window.recoveryToken}});window.recoveryToken=null;toast(r.message);location.hash='login';});
}
function loginHTML(){return `<div class="eyebrow mb">SELAMAT DATANG DI<br><span class="login-system-name">ECB LANGUAGE PERFORMANCE SYSTEM</span></div><h2>Mulai langkah Anda.</h2><p>Masuk untuk melanjutkan pembelajaran dan melihat perkembangan.</p><div class="auth-tabs"><button data-portal="employee" class="${loginPortal==='employee'?'selected':''}">Employee Portal</button><button data-portal="leader" class="${loginPortal==='leader'?'selected':''}">Leader Portal</button></div>${loginPortal==='leader'?'<div class="notice">Gunakan akun bersama yang diberikan perusahaan. Portal Leader hanya untuk melihat data.</div>':''}<form id="login-form"><label class="field">${loginPortal==='leader'?'Username Leader':'Nomor ID / Username'}<input name="username" required autocomplete="username" placeholder="${loginPortal==='leader'?'Username perusahaan':'Masukkan nomor ID Anda'}"></label><label class="field">Password<input name="password" type="password" required autocomplete="current-password" placeholder="Masukkan password Anda" maxlength="128"></label><div class="auth-actions"><a href="#forgot">Lupa password?</a></div><div class="form-error" role="alert"></div><button class="btn submit" type="submit">Masuk ke portal &nbsp; →</button></form>${loginPortal==='employee'?'<div class="auth-bottom">Belum punya akun? <a href="#register">Daftar sebagai karyawan</a></div>':''}${meta.demo?'<div class="auth-demo"><strong>Akun uji development</strong><br>Employee: DEMO001 (baru), DEMO002 (sudah placement)<br>Leader: LEADER<br>Password: <strong>DemoMandarin!2026</strong></div>':''}`;}
function registerHTML(){return `<div class="eyebrow mb">EMPLOYEE PORTAL</div><h2>Perjalanan dimulai di sini.</h2><p>Buat akun karyawan. Username otomatis mengikuti nomor ID Anda.</p><form id="register-form" class="form-grid"><label class="field full">Nama lengkap<input name="name" minlength="3" maxlength="100" required autocomplete="name"></label><label class="field">Nomor ID<input name="employee_id" pattern="(?:[A-Za-z0-9]|-){3,30}" required maxlength="30"></label><label class="field">Departemen<select aria-label="Departemen" name="department" required><option value="">Pilih departemen</option>${meta.departments.map(d=>`<option>${esc(d.id)}</option>`).join('')}</select></label><label class="field">Divisi<input name="division" required minlength="2" maxlength="80"></label><label class="field">Jabatan<input name="job_title" required minlength="2" maxlength="80"></label><label class="field full">Email pemulihan<input aria-label="Email pemulihan" name="email" type="email" autocomplete="email" required maxlength="200"><small>Digunakan untuk pemulihan password yang aman.</small></label><label class="field full">Level Mandarin (HSK) menurut Anda<select aria-label="Level self-assessed" name="self_level">${[1,2,3,4,5,6].map(l=>`<option value="${l}">Level ${l}</option>`).join('')}</select><small>Terpisah dari hasil placement internal.</small></label><label class="field full">Buat password<input aria-label="Buat password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>Minimal 12 karakter: huruf besar, kecil, angka dan simbol.</small></label><div class="form-error full" role="alert"></div><button class="btn submit full" type="submit">Daftar sebagai karyawan →</button></form><div class="auth-bottom">Sudah punya akun? <a href="#login">Masuk</a></div>`;}
function forgotHTML(){return '<div class="eyebrow mb">PEMULIHAN AKUN</div><h2>Lupa password?</h2><p>Masukkan nomor ID. Petunjuk pemulihan dikirim ke email yang terdaftar bila layanan tersedia.</p><form id="forgot-form"><label class="field">Nomor ID<input name="username" required autocomplete="username"></label><div class="form-error" role="alert"></div><button class="btn submit" type="submit">Kirim petunjuk pemulihan</button></form><p id="auth-message" class="notice mt" role="status">Pada mode lokal, layanan email belum terhubung. Pemulihan oleh IT tersedia melalui CLI.</p><a href="#login">← Kembali masuk</a>';}
function resetHTML(){return '<h2>Buat password baru</h2><form id="reset-form"><label class="field">Password baru<input aria-label="Buat password" name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"><small>Huruf besar, kecil, angka dan simbol.</small></label><div class="form-error" role="alert"></div><button type="submit" class="btn">Simpan password</button></form>';}
function historyHTML(history){if(!history.length)return empty('Belum ada riwayat ujian','Mulai dari placement untuk mengetahui level belajar Anda.');return `<div class="table-wrap"><table><thead><tr><th>UJIAN</th><th>TANGGAL WITA</th><th>NILAI</th><th>STATUS</th><th></th></tr></thead><tbody>${history.map(r=>`<tr><td><strong>${esc(r.track.toUpperCase())}</strong> · ${esc(modeLabel(r.mode))}${r.official?' '+badge('Resmi','green'):''}</td><td>${date(r.started_at,true)}</td><td>${num(r.score,1)}</td><td>${r.status==='active'?badge('Berlangsung','gold'):r.status==='submitted'&&r.score==null?badge('Menunggu penilaian','gold'):r.status==='void'?badge('Invalid','red'):badge(r.passed?'Lulus':'Selesai · belum lulus',r.passed?'green':'gold')}</td><td><a href="#exam/${r.id}">${r.status==='active'?'Lanjutkan':'Pembahasan'} →</a></td></tr>`).join('')}</tbody></table></div>`;}
const modeLabel=m=>({weekly:'Weekly Assessment',placement:'Placement Skill',levelup:'Ujian Naik Level',hsk_simulation:'Simulasi HSK penuh',hsk_learning:'HSK mode belajar',hsk_section:'Latihan bagian HSK',hsk_mistakes:'Latihan soal salah',diagnostic:'Work Diagnostic',random30:'Random 30',random100:'Random 100',grammar:'Grammar Quiz',translation:'Translation Quiz'}[m]||m);
function trend(history){const rows=history.filter(r=>r.official&&r.status==='submitted').slice(0,8).reverse();if(!rows.length)return empty('Tren akan tumbuh bersama Anda','Nilai assessment resmi akan muncul di sini.');return `<svg class="chart" viewBox="0 0 500 170" role="img" aria-label="Tren nilai assessment resmi">${[0,50,100].map(n=>`<text x="0" y="${145-n*1.2}">${n}</text><path d="M30 ${140-n*1.2}H490" stroke="#e4ece8"/>`).join('')}<path class="chart-pass-line" d="M30 44H490" fill="none" stroke="#e890a5" stroke-width="2" stroke-dasharray="6 5"><title>Batas kelulusan mingguan: 80</title></path>${['hsk','work'].map((track,j)=>{const points=rows.map((r,i)=>({r,x:45+i*425/Math.max(1,rows.length-1),y:140-Number(r.score)*1.2})).filter(p=>p.r.track===track);return `<polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="${j?'#b58a35':'#147d79'}" stroke-width="2.5"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="4" fill="${j?'#b58a35':'#147d79'}"><title>${date(p.r.started_at,true)}: ${p.r.score}</title></circle>`).join('')}`;}).join('')}${rows.map((r,i)=>`<text x="${45+i*425/Math.max(1,rows.length-1)}" y="164" text-anchor="middle">${date(r.started_at,true)}</text>`).join('')}</svg>`;}
async function dashboard(){const viewVersion=routeVersion;const learningSummary=api('/learn/summary');learningSummary.catch(()=>{});const [d,widgets,plan]=await Promise.all([api('/dashboard'),import('./learning-center.js'),import('./dashboard-plan.js')]);const l={level:d.profile.placement_level||1};if(viewVersion!==routeVersion)return;user=d.profile;const w=d.weekly,completed=Number(!!w.hsk)+Number(!!w.work),level=user.placement_level;const mission=(track,label,copy)=>{const result=w[track];return `<div class="mission"><div class="mission-icon">${track==='hsk'?'文':'工'}</div><div class="mission-body"><strong>${label}</strong><p>${esc(copy)} · ${result?`Nilai ${num(result.score)}`:'30 soal · 25 menit'}</p></div>${result?badge(result.passed?'Lulus':'Selesai',result.passed?'green':'gold'):`<button class="btn secondary" data-start="weekly" data-track="${track}">Mulai →</button>`}</div>`;};
 if(viewVersion!==routeVersion)return;shell('dashboard','Dashboard',`<div class="dashboard-redesign">`+heading('YOUR LEARNING JOURNEY',`Selamat datang, ${user.name.replace('DEMO · ','').split(' ')[0]}.`,'Langkah kecil hari ini, kemampuan yang lebih baik esok hari.',`<div class="date-chip">${date(Date.now()/1000)} · WITA</div>`)+`<section class="hero dashboard-welcome"><div class="dashboard-welcome-copy"><span class="eyebrow">${level?'TERUSKAN PERKEMBANGAN ANDA':'LANGKAH PERTAMA'}</span><h2>${level?`Anda belajar di HSK ${level}.`:'Kenali kemampuan Mandarin Anda.'}</h2><p>${level?'Luangkan waktu untuk belajar, lalu tuntaskan dua assessment wajib minggu ini.':'Selesaikan placement adaptif untuk menentukan level belajar. Hasil ini merupakan evaluasi internal, bukan sertifikasi HSK resmi.'}</p>${level?`<div class="dashboard-actions"><a class="btn" href="${esc(widgets.learningResume(l).href)}">Lanjutkan belajar →</a><a class="btn secondary" href="#levelup">Ujian Naik Level →</a></div>`:'<button class="btn" data-start="placement" data-track="hsk">Mulai / lanjutkan placement →</button>'}</div><img class="dashboard-welcome-panda" src="/dash-welcome.webp" width="560" height="420" alt="" fetchpriority="high" decoding="async"></section><section class="panel mb dashboard-target-panel"><div class="notice" id="dashboard-countdown" aria-label="Waktu tersisa" hidden></div><h2 class="dash-icon-heading">${widgets.dashboardIcon('target')}<span>Target Belajar Mandarin</span></h2><div id="dashboard-plan">Memuat target…</div><p id="dashboard-plan-error" role="status"></p></section><div id="dashboard-learning" aria-busy="true"></div><div class="grid2 dashboard-evaluation-row"><section class="panel dashboard-evaluation"><div class="panel-head"><h2 class="dash-icon-heading">${widgets.dashboardIcon('evaluation')}<span>Evaluasi minggu ini</span></h2>${badge('Minggu berjalan','green')}</div>${mission('hsk','HSK Weekly Assessment',level?`Sesuai level HSK ${level}`:'Placement diperlukan')}${mission('work','Work Weekly Assessment','18 umum + 12 departemen')}<div class="progress-copy"><span>Belajar aktif</span><strong>${num(w.minutes)} / 60 menit</strong></div><div class="progress"><span data-progress="${Math.min(100,w.minutes/60*100)}"></span></div><p class="weekly-note">${date(w.start,true)} – ${date(w.end-1,true)} · Tenggat Minggu 23.59 WITA.<br>Selesai dan lulus merupakan status yang berbeda.</p></section><section class="panel dashboard-score"><div class="panel-head"><h2 class="dash-icon-heading">${widgets.dashboardIcon('chart')}<span>Perkembangan nilai</span></h2><small>Assessment resmi</small></div><div class="legend"><span><i></i>HSK</span><span><i class="gold"></i>Work</span></div>${trend(d.history)}</section></div><section class="panel mb dashboard-history-panel"><h2 class="dash-icon-heading">${widgets.dashboardIcon('history')}<span>Riwayat saya</span></h2>${[['exams','Riwayat ujian'],['xp','Riwayat XP'],['learning','Riwayat belajar aktif'],['activities','Riwayat aktivitas latihan']].map(([kind,label])=>`<details class="dashboard-history" data-dashboard-history="${kind}"><summary>${widgets.dashboardIcon(({exams:'evaluation',xp:'xp',learning:'book',activities:'target'})[kind])}<span>${label}</span></summary>${kind==='exams'?`<p>Baseline HSK: ${num(user.baseline_hsk,1)} · Baseline Work: ${num(user.baseline_work,1)}</p>`:''}<div class="dashboard-history-list" aria-live="polite"></div><button class="btn secondary mt" type="button" hidden>Muat lebih banyak</button></details>`).join('')}</section><div class="grid2 dashboard-bottom-row"><section class="panel dashboard-reminders"><div class="panel-head"><h2 class="dash-icon-heading">${widgets.dashboardIcon('bell')}<span>Pengingat Anda</span></h2><small>In-app</small></div><div class="dashboard-notification-list">${d.notifications.length?d.notifications.map(n=>`<div class="notification ${n.read_at?'read':''}"><div>${esc(n.message)}<br><small>${date(n.created_at,true)}</small></div>${n.read_at?'':`<button data-read="${n.id}">Tandai dibaca</button>`}</div>`).join(''):empty('Anda sudah mengetahui langkah berikutnya','Pengingat progres tersedia pada Senin, Kamis, Sabtu dan Minggu.')}</div></section><section class="panel recommend-friend"><div><div class="panel-head"><h2 class="dash-icon-heading">${widgets.dashboardIcon('book')}<span>Rekomendasi berikutnya</span></h2></div><p class="muted">${level?`Pelajari paket HSK ${level} dan kosakata kerja departemen ${esc(user.department)} sebelum assessment.`:'Mulai dengan placement untuk membuka assessment HSK sesuai level Anda.'}</p>${user.baseline_work==null?'<button class="btn secondary" data-start="diagnostic" data-track="work">Mulai Work Diagnostic →</button>':'<a class="btn secondary" href="#learning">Buka materi belajar →</a>'}</div><img src="/recommend-panda.webp" width="380" height="253" alt="" loading="lazy" decoding="async"></section></div></div>`);const dashRoot=root.querySelector('.dashboard-redesign');const journey=document.createElement('div');journey.className='dashboard-journey';dashRoot.querySelector('.dashboard-welcome').before(journey);journey.append(dashRoot.querySelector('.dashboard-target-panel'),dashRoot.querySelector('.dashboard-welcome'));applyProgress();wireStarts();void learningSummary.then(summary=>{if(viewVersion!==routeVersion)return;const node=$('#dashboard-learning');if(!node)return;node.innerHTML=widgets.learningOverview(summary,esc);node.removeAttribute('aria-busy');const resume=document.querySelector('.dashboard-actions a');if(resume)resume.href=widgets.learningResume(summary).href;}).catch(error=>{if(viewVersion!==routeVersion)return;const node=$('#dashboard-learning');if(node){node.removeAttribute('aria-busy');node.innerHTML=`<div class="notice error" role="alert">${esc(error.message)} <button class="btn secondary" id="retry-learning-summary">Coba lagi</button></div>`;$('#retry-learning-summary').onclick=route;}});cleanup();plan.mountDashboardPlan({api,root,esc,date,fmtTime,historyHTML,cleanup:fn=>{cleanup=fn;}});document.querySelectorAll('[data-read]').forEach(b=>b.onclick=async()=>{try{await api(`/notifications/${b.dataset.read}/read`,{method:'POST',body:{}});await dashboard();}catch(e){toast(e.message);}});}
function applyProgress(){document.querySelectorAll('[data-progress]').forEach(el=>{el.style.width=Math.max(0,Math.min(100,Number(el.dataset.progress)))+'%';});}
function wireStarts(){document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const q=await api('/exams',{method:'POST',body:{mode:b.dataset.start,track:b.dataset.track}});location.hash='exam/'+q.id;}catch(e){toast(e.message);b.disabled=false;}});}
