async function packagePage(pid){const viewVersion=routeVersion;const p=await api('/packages/'+pid);let session=null,activeSeconds=0,lastInteraction=Date.now(),pending=false;function render(){if(viewVersion!==routeVersion)return;shell('learning','Learning',heading(p.track==='hsk'?`HSK ${p.level}`:'WORK VOCABULARY',p.title,'Baca Hanzi, ucapkan Pinyin, dan pahami maknanya.')+`<a href="#learning">← Kembali ke paket</a>${meta.source_content?'<div class="notice mt">Materi sumber HSK 3.0 dan kosakata kerja. Soal menggunakan kosakata, konteks, dan grammar sesuai level sumber.</div>':meta.demo?'<div class="notice mt">Fixture khusus pengujian.</div>':''}${(p.words.length||p.lessons?.length)?`<div class="learning-bar"><span><span class="active-pill"></span>Waktu aktif sesi: <strong id="learning-time">00:00</strong><br><small id="learning-status">Mulai sesi untuk mencatat waktu belajar aktif.</small></span><div class="split">${speechSettings()}<button class="btn" id="start-learning">Mulai sesi belajar</button><button class="btn secondary" id="finish-learning" disabled>Selesaikan sesi</button></div></div><div id="memory-summary">${p.words.length?memorySummary(p.words):''}</div><div class="word-grid">${p.words.map(w=>`<article class="panel word" data-vocab="${w.id}"><div class="hanzi" lang="zh">${esc(w.hanzi)}</div>${speakButton(w.hanzi)}<div class="pinyin">${esc(w.pinyin)}</div><div class="meaning">${esc(w.meaning)}</div>${meta.source_content?sourceRef(w.source_ref):''}${meta.source_content&&w.examples?wordExamples(w.examples):''}${memoryButtons(w)}</article>`).join('')}</div>${(p.lessons||[]).length?'<section class="mt"><h2>Grammar, contoh & bacaan sumber</h2>'+p.lessons.map(lessonHTML).join('')+'</section>':''}<p class="weekly-note">Waktu divalidasi server: heartbeat 15 detik, idle 60 detik, maksimal sesi 30 menit. Sesi yang selesai minimal 15 detik dapat menandai progres paket.</p>`:empty('Materi sedang ditinjau','Konten draft dan under review belum dapat dipelajari sebagai materi resmi.')}`);bind('#start-learning','click',async()=>{try{session=await api('/learning/start',{method:'POST',body:{package_id:pid}});lastInteraction=Date.now();$('#start-learning').disabled=true;$('#finish-learning').disabled=false;$('#learning-status').textContent='Sesi aktif. Interaksi diperlukan agar waktu terus dihitung.';}catch(e){toast(e.message);}});bind('#finish-learning','click',async()=>{if(!session)return;try{const r=await beat(true);session=null;toast(r.completed?'Progres paket tersimpan.':'Sesi tersimpan; belajar aktif minimal 15 detik untuk menyelesaikan paket.');$('#finish-learning').disabled=true;$('#start-learning').disabled=false;}catch(e){toast(e.message);}});}
 async function beat(complete=false){if(pending)return {};pending=true;try{const r=await api(`/learning/${session.id}/heartbeat`,{method:'POST',body:{active:document.visibilityState==='visible'&&Date.now()-lastInteraction<60000,complete}});activeSeconds=r.active_seconds;$('#learning-time').textContent=fmtTime(activeSeconds);$('#learning-status').textContent=r.closed?'Sesi ditutup.':'Waktu aktif tervalidasi server.';if(r.closed)session=null;return r;}finally{pending=false;}}
 const activity=()=>{lastInteraction=Date.now();};['pointerdown','keydown','scroll','touchstart'].forEach(e=>document.addEventListener(e,activity,{passive:true}));render();applyProgress();wireMemory(p.words);document.querySelectorAll('.lesson-body p').forEach(line=>{if(/\p{Script=Han}/u.test(line.textContent))line.insertAdjacentHTML('afterend',speakButton(line.textContent));});const disposeSpeech=wireSpeech(root,{notify:toast});const timer=setInterval(()=>{if(session)beat().catch(e=>{if($('#learning-status'))$('#learning-status').textContent=e.message;});},15000);cleanup=()=>{disposeSpeech();clearInterval(timer);['pointerdown','keydown','scroll','touchstart'].forEach(e=>document.removeEventListener(e,activity));};}
