async function examPage(sid){const viewVersion=routeVersion;const official=await api('/exams/'+sid);if(viewVersion!==routeVersion)return;if(official.format==='placement-first-error-v2'){const {mountPlacementExam}=await import('./placement-exam.js');if(viewVersion!==routeVersion)return;await mountPlacementExam(official,{api,shell,esc,setCleanup:fn=>{cleanup=fn;},readOnly:user.role==='leader'});return;}if(official.format==='official_archive'){const {mountOfficialExam}=await import('./official-exam.js');if(viewVersion!==routeVersion)return;const owner=user.role==='leader'?(await api('/leader/employees/'+official.user_id)).profile:null;if(viewVersion!==routeVersion)return;await mountOfficialExam(official,{api,shell,heading,esc,fmtTime,toast,readOnly:user.role==='leader',ownerName:owner?.name||'',setCleanup:fn=>{cleanup=fn;}});return;}let q=official,index=0,answers={...q.answers},dirty={},saving=false,disposed=false,remaining=Math.max(0,q.deadline-q.server_now),syncBase=Date.now();
 if(q.result){await resultPage(q,true);return;}
 function render(){const item=q.questions[index];if(viewVersion!==routeVersion)return;shell('examination','Ujian berlangsung',heading(q.mode==='weekly'?'WEEKLY ASSESSMENT':'INTERNAL ASSESSMENT',`${q.track.toUpperCase()} · ${modeLabel(q.mode)}`,`Level ${q.level} · ${q.questions.length} soal · ${q.assessment?.content_mode==='source'?'HSK 3.0 · materi sumber · ':meta.demo?'DEMO · ':''}Satu jawaban benar per soal`)+`<div class="quiz-layout"><section class="panel"><span class="eyebrow">SOAL ${index+1} DARI ${q.questions.length}</span><h2 class="quiz-question">${readingHTML(item.prompt,item.prompt_reading)}</h2><fieldset class="quiz-options"><legend class="sr-only">Pilih jawaban</legend>${item.options.map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${o.id}" ${answers[item.id]===o.id?'checked':''}><span>${String.fromCharCode(65+i)}.</span><span class="option-reading">${readingHTML(o.label,o.reading)}</span></label>`).join('')}</fieldset><div class="quiz-controls"><button class="btn secondary" id="previous" ${index===0?'disabled':''}>← Sebelumnya</button><button class="btn secondary" id="next" ${index===q.questions.length-1?'disabled':''}>Selanjutnya →</button></div><p class="weekly-note" id="save-status" aria-live="polite">${Object.keys(dirty).length?'Menyimpan jawaban…':'Jawaban tersimpan di server.'}</p></section><aside class="panel quiz-side"><span class="eyebrow">SISA WAKTU</span><div class="timer" id="exam-timer">${fmtTime(remaining-Math.floor((Date.now()-syncBase)/1000))}</div><p>Waktu server berlaku. Saat habis, jawaban tersimpan disubmit otomatis.</p><div class="question-grid">${q.questions.map((r,i)=>`<button class="${answers[r.id]?'answered':''} ${i===index?'current':''}" data-question="${i}" aria-label="Buka soal ${i+1}">${i+1}</button>`).join('')}</div><div class="progress-copy"><span>Progres jawaban</span><strong id="answer-percent">${Math.round(Object.keys(answers).length/q.questions.length*100)}%</strong></div><div class="progress"><span id="exam-answer-progress" data-progress="${Object.keys(answers).length/q.questions.length*100}"></span></div><p id="answer-count">${Object.keys(answers).length} / ${q.questions.length} terjawab</p><button class="btn" id="submit-exam">Selesaikan & kirim →</button><p id="submit-hint">Periksa jawaban sebelum mengirim.</p></aside></div>`);applyProgress();$('.quiz-options').style.border='0';$('.quiz-options').style.padding='0';
 document.querySelectorAll('[name=answer]').forEach(r=>r.onchange=()=>{answers[item.id]=r.value;dirty[item.id]=r.value;$('#save-status').textContent='Menyimpan jawaban…';const grid=document.querySelector(`[data-question="${index}"]`);grid.classList.add('answered');$('#answer-count').textContent=`${Object.keys(answers).length} / ${q.questions.length} terjawab`;$('#answer-percent').textContent=Math.round(Object.keys(answers).length/q.questions.length*100)+'%';$('#exam-answer-progress').style.width=Object.keys(answers).length/q.questions.length*100+'%';flush();});bind('#previous','click',()=>{index--;render();});bind('#next','click',()=>{index++;render();});document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{index=Number(b.dataset.question);render();});bind('#submit-exam','click',async()=>{if(await confirmSubmit(root))await submit();});
 }
 async function flush(){if(saving||!Object.keys(dirty).length||disposed)return;saving=true;const batch={...dirty};try{const r=await api(`/exams/${sid}/answers`,{method:'PUT',body:{answers:batch}});if(disposed)return;if(r.result){disposed=true;cleanup();await resultPage(r,true);return;}for(const [key,value]of Object.entries(batch))if(dirty[key]===value)delete dirty[key];if($('#save-status'))$('#save-status').textContent=Object.keys(dirty).length?'Menyimpan jawaban…':'Jawaban tersimpan di server.';}catch(e){if($('#save-status'))$('#save-status').textContent=e.message;}finally{saving=false;}}
 async function submit(){const b=$('#submit-exam');if(b)b.disabled=true;try{q=await api(`/exams/${sid}/submit`,{method:'POST',body:{answers}});disposed=true;cleanup();await resultPage(q,true);}catch(e){toast(e.message);if(b)b.disabled=false;}}
 render();const interval=setInterval(()=>{if(disposed)return;const left=remaining-Math.floor((Date.now()-syncBase)/1000);if($('#exam-timer'))$('#exam-timer').textContent=fmtTime(left);if(left<=0)submit();else flush();},1000);cleanup=()=>{disposed=true;clearInterval(interval);};
}
async function resultPage(q,autoAdvance=false){const viewVersion=routeVersion,me=await api('/me');if(viewVersion!==routeVersion)return;user=me.user;const owner=user.role==='leader'?(await api('/leader/employees/'+q.user_id)).profile:null;if(viewVersion!==routeVersion)return;const next=user.role==='employee'&&q.continuation;if(next&&autoAdvance){try{const following=await api('/exams',{method:'POST',body:{track:'hsk',mode:next.mode}});toast(`Lulus HSK ${q.level}. Melanjutkan ke HSK ${following.level}.`);location.hash='exam/'+following.id;return;}catch(error){toast(error.message);}}const questions=q.questions;shell(user.role==='leader'?'results':'examination','Hasil ujian',heading('REFLECT, THEN MOVE FORWARD',owner?owner.name:'Setiap hasil adalah langkah maju.',`${q.track.toUpperCase()} · ${modeLabel(q.mode)} · ${date(q.submitted_at||q.started_at)}`,'',!!owner)+`${q.status==='void'?'<div class="notice error">Arsip hasil lama/fixture. Nilai ini tidak digunakan untuk placement atau ranking HSK 3.0. Mulai placement baru dari Dashboard.</div>':''}<section class="panel mb"><div class="grid2"><div><div class="eyebrow">${owner?'NILAI KARYAWAN':'NILAI ANDA'} ${q.official?'· RESMI':'· NON-RANKING'}</div><div class="result-score">${num(q.result.score,1)}<small> /100</small></div>${badge(q.result.passed?'Lulus':'Selesai · belum lulus',q.result.passed?'green':'gold')}<p class="muted mt">Ambang kelulusan ${q.pass_threshold??80}. ${q.official?'Hasil valid pertama tersimpan sebagai nilai resmi.':'Hasil ini tidak menimpa nilai resmi mingguan.'}</p></div><div><h2>${owner?'Catatan evaluasi':'Langkah berikutnya'}</h2><p class="muted">${owner?'Hasil ditampilkan untuk pendampingan karyawan. Portal Leader tidak mengubah nilai atau level.':next?'Anda melewati ambang tahap ini. Ujian level berikutnya akan terbuka otomatis.':q.mode==='levelup'?`Ujian naik level selesai. Level belajar Anda: HSK ${user.placement_level}.`:q.mode==='placement'?`Placement internal selesai. Level belajar Anda: HSK ${user.placement_level}.`:'Pelajari kembali materi yang belum dipahami, lalu gunakan latihan untuk memperkuat kemampuan.'}</p>${next?'<button class="btn" data-start="'+next.mode+'" data-track="hsk">Lanjutkan ke level berikutnya →</button>':user.role==='employee'?'<a class="btn" href="#learning">Kembali belajar →</a>':'<a class="btn" href="#results">Kembali ke hasil →</a>'}</div></div></section><section class="panel"><div class="panel-head"><h2>Pembahasan lengkap</h2><small>Snapshot konten saat sesi dimulai</small></div>${questions.length?questions.map((r,i)=>`<article class="review"><h3>${i+1}. ${readingHTML(r.prompt,r.prompt_reading)}</h3><ul>${r.options.map(o=>`<li class="${o.id===r.correct_id?'correct':o.id===r.selected?'wrong':''}"><span data-i18n-skip>${readingHTML(o.label,o.reading)}</span> ${o.id===r.correct_id?'<span>✓ Jawaban benar</span>':''}${o.id===r.selected?'<span> · Pilihan Anda</span>':''}</li>`).join('')}</ul>${r.selected?'':'<p>Tidak dijawab.</p>'}<p data-i18n-skip>${esc(r.explanation)}</p>${sourceRef(r.source_ref)}</article>`).join(''):empty('Riwayat sintetis DEMO','Fixture ringkasan historis tidak memuat snapshot soal. Ujian baru selalu menyimpan snapshot lengkap.')}</section>`);wireStarts();}
async function ranking(){const version=routeVersion;const {mountAchievements}=await import('./achievements.js');if(version!==routeVersion)return;await mountAchievements({api,shell,esc,root,user,cleanup:fn=>{cleanup=fn;}});}
async function profile(editing=false){const viewVersion=routeVersion;
 const d=await api('/dashboard');if(viewVersion!==routeVersion)return;user=d.profile;
 const summary = [
  ['ranking','Level HSK',user.placement_level ? 'HSK '+user.placement_level : 'Belum selesai'],
  ['learning','Departemen',user.department],
  ['work','Jabatan',user.job_title]
 ];
 shell('profile','Profile',`<div class="employee-profile">`+
 heading('YOUR PERSONAL SPACE','Profil Anda.','Kelola informasi pribadi dan data pekerjaan Anda.',
 '<button type="button" id="edit-profile" class="btn secondary">'+icon('edit')+'Edit profil</button>')+
 `<dl class="profile-summary">${summary.map(([symbol,label,value])=>`<div class="profile-summary-item">
 <span class="profile-symbol">${icon(symbol)}</span><div><dt>${label}</dt><dd>${esc(value||'—')}</dd></div></div>`).join('')}</dl>
 <section class="panel employee-profile-panel"><div class="panel-head"><h2><span class="profile-symbol">${icon('profile')}</span><span>Informasi karyawan</span></h2>${badge('Employee','green')}</div>
 <form id="profile-form"><fieldset id="profile-fields" class="profile-fields" disabled><div class="form-grid">
 <label class="field">Nomor ID<input name="employee_id" value="${esc(user.employee_id)}" required pattern="[A-Za-z0-9-]{3,30}" maxlength="30"><small>Nomor ID digunakan sebagai username login. Gunakan ID baru setelah disimpan.</small></label>
 <label class="field">Departemen<select name="department">${meta.departments.map(item=>`<option value="${esc(item.id)}" ${item.id===user.department?'selected':''}>${esc(item.id)}</option>`).join('')}</select></label>
 <label class="field">Divisi<input name="division" value="${esc(user.division)}" required minlength="2" maxlength="80"></label>
 <label class="field">Jabatan<input name="job_title" value="${esc(user.job_title)}" required minlength="2" maxlength="80"></label>
 <label class="field full">Nama lengkap<input name="name" value="${esc(user.name)}" required minlength="3" maxlength="100"></label>
 <label class="field full">Email pemulihan<input name="email" type="email" value="${esc(user.email)}" required maxlength="200"><small>Pastikan alamat benar dan dapat Anda akses untuk pemulihan password.</small></label>
 <label class="field full">Level self-assessed<select aria-label="Level self-assessed" name="self_level">${[1,2,3,4,5,6].map(level=>`<option value="${level}" ${level===user.self_level?'selected':''}>${level}</option>`).join('')}</select><small>Mengubah self-assessed tidak menaikkan level placement.</small></label>
 </div><label class="field" id="profile-password-field" hidden>Password saat ini<input name="current_password" type="password" autocomplete="current-password" maxlength="128"><small>Diperlukan hanya saat mengubah Nomor ID atau email pemulihan.</small></label><label class="check-label"><input type="checkbox" name="in_app" ${d.preferences.in_app?'checked':''}>Aktifkan pengingat in-app</label></fieldset>
 <div class="form-error" role="alert"></div><div id="profile-actions" class="split" hidden><button class="btn" type="submit">Simpan profil</button><button class="btn secondary" type="button" id="cancel-profile">Batal</button></div></form>
 <div class="notice mt profile-placement"><span class="profile-symbol">${icon('info')}</span><div><strong>Placement: ${user.placement_level?'HSK '+user.placement_level:'Belum selesai'} · Baseline HSK: ${num(user.baseline_hsk)} · Baseline Work: ${num(user.baseline_work)}.</strong><br>Perubahan departemen berlaku pada materi berikutnya.</div></div></section></div>`);
 const enable=()=>{$('#profile-fields').disabled=false;$('#profile-actions').hidden=false;$('#edit-profile').hidden=true;};
 bind('#edit-profile','click',enable);bind('#cancel-profile','click',()=>profile());if(editing)enable();
 const checkIdentity=()=>{const changed=$('[name=employee_id]').value.toUpperCase()!==user.employee_id||$('[name=email]').value.toLowerCase()!==user.email;$('#profile-password-field').hidden=!changed;$('[name=current_password]').required=changed;};bind('[name=employee_id]','input',checkIdentity);bind('[name=email]','input',checkIdentity);
 form('#profile-form',async fd=>{user=await api('/profile',{method:'PATCH',body:{employee_id:fd.get('employee_id'),email:fd.get('email'),current_password:fd.get('current_password'),name:fd.get('name'),department:fd.get('department'),division:fd.get('division'),job_title:fd.get('job_title'),self_level:Number(fd.get('self_level')),in_app:fd.has('in_app')}});await profile();toast('Profil tersimpan.');});
}

async function leaderPage(page){const version=routeVersion;const {mountLeaderPortal}=await import('./leader-portal.js');if(version!==routeVersion)return;await mountLeaderPortal({api,shell,esc,root,user,cleanup:fn=>{cleanup=fn;}},page);}
async function employeePage(uid){const version=routeVersion;const {mountLeaderEmployee}=await import('./leader-portal.js');if(version!==routeVersion)return;await mountLeaderEmployee({api,shell,esc,root,cleanup:fn=>{cleanup=fn;}},uid);}
async function route(){stopSpeech();cleanup();cleanup=()=>{};const version=++routeVersion;let [page,arg]=(location.hash.slice(1)||'').split('?')[0].split('/');if(page==='recovery'&&window.recoveryToken){authView('recovery');return;}if(!user){authView(['register','forgot','recovery'].includes(page)?page:'login');return;}if(!page||['login','register','forgot'].includes(page)){location.hash=user.role==='leader'?'overview':'dashboard';return;}
 const allowed=user.role==='leader'?['learning-analytics','overview','employees','results','ranking','employee','exam']:['dashboard','learning','learning-mistakes','study','saved','recall','grammar','practice','story','speaking','songs','chengyu','hanzi','hanzi-compare','pinyin','pinyin-mistakes','vocab-atlas','word-pairs','pair-practice','pair-mistakes','package','examination','exam','ranking','profile','levelup','source'];if(!allowed.includes(page)){location.hash=user.role==='leader'?'overview':'dashboard';return;}
 if(!root.querySelector('.shell'))shell(page,{dashboard:'Dashboard',learning:'Learning',examination:'Examination',ranking:'Ranking',profile:'Profile',overview:'Overview',employees:'Employees',results:'Results','learning-analytics':'Analitik Pembelajaran'}[page]||'Portal',heading('PORTAL ECB',`Selamat datang, ${esc(user.name.replace('DEMO · ','').split(' ')[0])}.`,'Pilih menu untuk melanjutkan aktivitas Anda.'));
 const pendingContent=$('#main-content');pendingContent?.setAttribute('aria-busy','true');
 try{if(page==='learning-analytics'){const {mountLearningAnalytics}=await import('./learning-analytics.js');await mountLearningAnalytics({api,shell,esc,root,cleanup:fn=>{cleanup=fn;}});}else if(page==='dashboard')await dashboard();else if(page==='learning')await learning();else if(page==='learning-mistakes')await learning('mistakes');else if(['practice','story','speaking','songs'].includes(page))await playPage(page,arg||'');else if(['hanzi','hanzi-compare','pinyin','pinyin-mistakes'].includes(page)){
  const {mountAtlas}=await import('./hanzi-atlas.js');
  if(version!==routeVersion)return;
  await mountAtlas({api,shell,esc,root,toast,cleanup:fn=>{cleanup=fn;}},page,arg||'');
 }else if(page==='chengyu'){const {mountChengyu}=await import('./chengyu.js');if(version!==routeVersion)return;await mountChengyu({api,shell,esc,root,toast,cleanup:fn=>{cleanup=fn;}},arg);}else if(['vocab-atlas','word-pairs','pair-practice','pair-mistakes'].includes(page)){
  const {mountVocabulary}=await import('./vocab-atlas.js');
  if(version!==routeVersion)return;
  await mountVocabulary({api,shell,esc,root,toast,cleanup:fn=>{cleanup=fn;}},page,decodeURIComponent(arg||''));
 }else if(page==='study')await learning('study',arg);else if(page==='saved')await mountSaved({api,shell,esc,root,toast,cleanup:fn=>{cleanup=fn;}});else if(page==='recall')await learning('recall',arg);else if(page==='grammar')await learning('grammar',arg);else if(page==='package')await packagePage(arg);else if(page==='examination')await examination();else if(page==='levelup')await levelUpPage();else if(page==='exam')await examPage(arg);else if(page==='ranking')await ranking(arg||'');else if(page==='profile')await profile(arg==='edit');else if(page==='source')await sourcePage(arg);else if(page==='employee')await employeePage(arg);else await leaderPage(page);}catch(e){if(version!==routeVersion)return;if(user)shell(page,'Informasi',heading('PORTAL ECB','Halaman belum dapat dimuat.','')+`<div class="notice error" role="alert">${esc(e.message)}</div><button class="btn" id="retry">Coba lagi</button>`);else authView();bind('#retry','click',route);}finally{if(version===routeVersion)$('#main-content')?.removeAttribute('aria-busy');}}
const prefetchPages={dashboard:['/dashboard','/learn/summary'],learning:['/learn/summary?view=center','/packages']};
function prefetchNavigation(event){
 const link=event.target.closest?.('.sidebar nav a');if(!link||!user||user.role!=='employee')return;
 const page=link.hash.slice(1);for(const path of prefetchPages[page]||[])void api(path).catch(()=>{});
 if(page==='dashboard'){void import('./learning-center.js');void import('./dashboard-plan.js');}
 if(page==='learning')void import('./learning-center.js');
}
root.addEventListener('pointerover',prefetchNavigation);
root.addEventListener('focusin',prefetchNavigation);
root.addEventListener('pointerdown',prefetchNavigation);
window.addEventListener('hashchange',route);
async function boot(){try{meta=await api('/meta');const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.get('type')==='recovery'&&fragment.get('access_token')){window.recoveryToken=fragment.get('access_token');history.replaceState(null,'','#recovery');}try{const me=await api('/me');user=me.user;csrf=me.csrf;}catch{}await route();}catch(e){root.innerHTML=empty('Server belum tersedia',e.message);}}
boot();
function parsed(value,fallback={}){try{return typeof value==='string'?JSON.parse(value):value||fallback;}catch{return fallback;}}
function sourceRef(value){return "";}

function wordExamples(value){const examples=parsed(value,[]);return examples.length?`<details class="source-examples"><summary>Contoh kalimat</summary>${examples.slice(0,2).map(e=>`<p lang="zh">${esc(e.zh)}</p>${speakButton(e.zh)}<p class="pinyin">${esc(e.pinyin)}</p><p>${esc(e.id)}</p>`).join('')}</details>`:'';}
function lessonHTML(lesson){const b=parsed(lesson.body),lines=v=>esc(v).replaceAll('\n','<br>');let body='';if(b.pattern)body=`<p><strong>Pola:</strong> ${lines(b.pattern)}</p><p>${lines(b.function)}</p><p lang="zh">${lines(b.examples_zh)}</p><p>${lines(b.examples_id)}</p>`;else if(b.paragraphs)body=b.paragraphs.map(p=>`<p>${lines(p)}</p>`).join('');else if(b.rows)body=b.rows.map(r=>`<div class="source-row">${r.cells.map(c=>`<p>${lines(c)}</p>`).join('')}</div>`).join('');return `<details class="panel source-lesson"><summary>${esc(lesson.title)} <span class="pill">${esc(lesson.kind)}</span></summary><div class="lesson-body"><div data-i18n-skip>${body}</div>${sourceRef(lesson.source_ref)}</div></details>`;}
async function sourcePage(assetId){const viewVersion=routeVersion;const a=await api('/library/'+assetId),detail=parsed(a.detail);if(viewVersion!==routeVersion)return;shell('learning','Sumber materi',heading(a.legacy?'ARSIP LATIHAN':'MATERI SUMBER',a.title,a.legacy?'Sumber HSK versi lama, terpisah dari bank assessment HSK 3.0.':'Dokumen dan latihan pendukung pembelajaran.','<a class="btn secondary" href="#learning">Semua sumber</a>')+`${a.status==='unreadable'?`<div class="notice error">${esc(detail.reason||'File belum dapat dibaca.')} Materi departemen tidak diganti dengan kosakata karangan.</div>`:detail.recovered?'<div class="notice">Worksheet dan data sumber dipulihkan dari arsip ZIP yang terpotong. File asli tidak diubah; pemulihan tercatat dalam laporan.</div>':''}${a.status==='available'&&a.media_type==='pdf'?`<section class="panel mb"><h2>Dokumen latihan</h2><p>${detail.pages||'—'} halaman. Baca sebagai latihan pelengkap; bukan sertifikasi atau kalibrasi level baru.</p><a class="btn" href="/api/library/${a.id}/file" target="_blank" rel="noopener">Buka PDF sumber ↗</a></section>`:''}${a.status==='available'&&a.media_type==='mp3'?`<section class="panel mb"><h2>Latihan mendengarkan</h2><audio controls preload="metadata" src="/api/library/${a.id}/file" class="w100">Browser Anda tidak mendukung audio.</audio><p class="weekly-note">Cari PDF dengan kode file yang sama dalam perpustakaan.</p></section>`:''}${['xlsx','docx'].includes(a.media_type)&&a.status==='available'?`<div class="notice">${detail.counts?.vocabulary||0} entri unik dipetakan dari sumber ini. Materi kosakata tersedia pada paket belajar; contoh, grammar dan bacaan ditampilkan di bawah bila tersedia. Workbook asli dengan kunci tidak dilayani sebagai file publik.</div><a class="btn secondary mb" href="#learning">Buka paket belajar →</a>${a.media_type==='docx'?'<a class="btn secondary mb" href="/api/library/'+a.id+'/file">Unduh dokumen asli & gambar ↓</a>':''}`:''}${a.media_type==='zip'?'<div class="notice">Arsip memuat sumber ujian lama. Gunakan PDF dan MP3 terpisah yang sudah tersedia pada perpustakaan.</div>':''}${a.lessons.map(lessonHTML).join('')}`);}
